-- =============================================================================
-- Stadion Maksimir — odbij javno poznate (slabe) ključeve glasača (nalaz I-09, 26. 9. 2026.)
--
-- Na Gnosisu je registriran commitment ključa od samih nula („abandon ×23 art”): testni ključ iz
-- faze 1 ostao je u pregledniku i ponuđen je kao pravi. Tajna tog ključa je javna, pa bi svatko
-- mogao mijenjati taj listić. Klijent (chain/client/keystore.ts) takve tajne sada odbija, a baza
-- dodatno odbija njihove commitmente, da ni zaobilaženje klijenta ne pomogne.
--
-- Slabo = 32 ista bajta (0x00…0xff). Commitment = Poseidon(javni ključ) — Postgres ga ne zna
-- izračunati, pa su svih 256 izračunati unaprijed (@semaphore-protocol/core 4.14, Identity.import).
-- Greška: weak_commitment
-- =============================================================================

create table if not exists domovina_ai.maksimir_weak_commitments (
  byte       smallint primary key check (byte between 0 and 255),
  commitment text not null unique
);
alter table domovina_ai.maksimir_weak_commitments enable row level security;
revoke all on domovina_ai.maksimir_weak_commitments from public, anon, authenticated;
grant select on domovina_ai.maksimir_weak_commitments to service_role;

on conflict (byte) do nothing;

create or replace function domovina_ai._maksimir_reject_weak_commitment()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  if exists (select 1 from domovina_ai.maksimir_weak_commitments w where w.commitment = new.commitment) then
    raise exception 'weak_commitment';
  end if;
  return new;
end;
$$;
revoke execute on function domovina_ai._maksimir_reject_weak_commitment() from public, anon, authenticated;

drop trigger if exists trg_maksimir_chain_reg_weak on domovina_ai.maksimir_chain_registrations;
create trigger trg_maksimir_chain_reg_weak
  before insert on domovina_ai.maksimir_chain_registrations
  for each row execute function domovina_ai._maksimir_reject_weak_commitment();

drop trigger if exists trg_maksimir_zk_members_weak on domovina_ai.maksimir_zk_members;
create trigger trg_maksimir_zk_members_weak
  before insert on domovina_ai.maksimir_zk_members
  for each row execute function domovina_ai._maksimir_reject_weak_commitment();

select 'OK maksimir_weak_keys' as status;
